input.content:
/* ============================================================
   Moss — warm, tactile, a little odd.
   ============================================================ */

:root {
  --bg: #f7f2e4;
  --bg-deep: #efe7d2;
  --card: #fffdf4;
  --ink: #31392b;
  --ink-soft: #61695a;
  --line: #e0d5b8;
  --line-strong: #cdbf9c;

  --moss: #5d7f4e;
  --moss-deep: #3f5c33;
  --leaf: #8ab06a;
  --leaf-tint: #e9f0dc;

  --terra: #c46a45;
  --terra-deep: #a34f2e;
  --terra-soft: #e3a184;
  --terra-tint: #f7e5da;

  --sun: #e7b24c;
  --sun-tint: #f9edcf;

  --drop: #6aa7d6;

  --focus: #274f6b;
  --shadow-clay: 0 3px 0 rgba(120, 100, 60, 0.18);
  --shadow-soft: 0 10px 24px rgba(80, 66, 36, 0.10);

  --radius-organic: 26px 30px 24px 28px / 28px 24px 30px 24px;
  --radius-panel: 30px 26px 30px 22px / 24px 30px 22px 30px;

  --font-display: Georgia, "Iowan Old Style", "Palatino Linotype", "Times New Roman", serif;
  --font-body: ui-rounded, "Avenir Next", Avenir, "Segoe UI", system-ui, -apple-system, "Helvetica Neue", Arial, sans-serif;
}

* { box-sizing: border-box; }

html { scroll-behavior: smooth; }

body {
  margin: 0;
  font-family: var(--font-body);
  font-size: 16px;
  line-height: 1.55;
  color: var(--ink);
  background-color: var(--bg);
  background-image: radial-gradient(rgba(120, 100, 60, 0.055) 1.1px, transparent 1.6px);
  background-size: 22px 22px;
  -webkit-font-smoothing: antialiased;
}

::selection { background: var(--sun); color: var(--ink); }

h1, h2, h3, h4 { font-family: var(--font-display); line-height: 1.2; margin: 0; font-weight: 700; }

p { margin: 0; }

ul, ol { margin: 0; padding: 0; list-style: none; }

button { font: inherit; color: inherit; }

.sr-only {
  position: absolute;
  width: 1px; height: 1px;
  margin: -1px; padding: 0;
  overflow: hidden;
  clip: rect(0 0 0 0);
  clip-path: inset(50%);
  white-space: nowrap;
  border: 0;
}

.skip {
  position: absolute;
  left: 12px; top: -64px;
  z-index: 60;
  background: var(--moss-deep);
  color: #fbf8ec;
  padding: 10px 18px;
  border-radius: 0 0 14px 14px;
  text-decoration: none;
  font-weight: 700;
  transition: top 0.18s ease;
}
.skip:focus { top: 0; }

:where(a, button, [tabindex]):focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 3px;
  border-radius: 6px;
}

.ico {
  width: 1em; height: 1em;
  flex: none;
  vertical-align: -0.125em;
}

.wrap {
  max-width: 1140px;
  margin: 0 auto;
  padding: 20px 16px 40px;
}

/* ---------- Masthead ---------- */

.top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  flex-wrap: wrap;
  padding: 6px 2px 20px;
}

.brand { display: flex; align-items: center; gap: 12px; }

.brand-mark {
  width: 46px; height: 46px;
  filter: drop-shadow(0 3px 0 rgba(120, 100, 60, 0.2));
  animation: brand-bob 5s ease-in-out infinite;
}

@keyframes brand-bob {
  0%, 100% { transform: rotate(-2deg); }
  50% { transform: rotate(2.5deg); }
}

.brand-text { display: grid; gap: 1px; }

.wordmark {
  font-size: 2rem;
  letter-spacing: 0.02em;
  color: var(--moss-deep);
}

.squiggle { width: 74px; height: 7px; display: block; }

.tagline {
  font-size: 0.82rem;
  color: var(--ink-soft);
  font-style: italic;
  font-family: var(--font-display);
}

.date-chip {
  background: var(--card);
  border: 1.6px solid var(--line);
  border-radius: 999px;
  padding: 7px 16px;
  font-size: 0.85rem;
  font-weight: 600;
  color: var(--ink-soft);
  box-shadow: var(--shadow-clay);
}

/* ---------- Layout ---------- */

.layout { display: grid; gap: 26px; }

.col-side { display: grid; gap: 20px; align-content: start; }

@media (min-width: 940px) {
  .wrap { padding: 32px 28px 56px; }
  .layout {
    grid-template-columns: minmax(0, 1.5fr) minmax(300px, 0.85fr);
    gap: 32px;
    align-items: start;
  }
  .col-side {
    position: sticky;
    top: 24px;
  }
}

/* ---------- Queue head ---------- */

.queue-head {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 16px;
  margin-bottom: 6px;
  flex-wrap: wrap;
}

#queue-title {
  font-size: clamp(1.5rem, 4vw, 1.9rem);
  color: var(--ink);
}

.lede {
  color: var(--ink-soft);
  margin-top: 4px;
  max-width: 46ch;
  font-size: 0.95rem;
}

.progress { display: flex; align-items: center; gap: 6px; padding-bottom: 4px; }

.pdot {
  width: 13px; height: 13px;
  border-radius: 50% 50% 50% 4px;
  border: 2px solid var(--moss);
  background: transparent;
  transform: rotate(45deg);
  transition: background-color 0.25s ease, transform 0.25s ease;
}
.pdot.filled {
  background: var(--moss);
  transform: rotate(45deg) scale(1.12);
}

.progress-label {
  font-size: 0.8rem;
  font-weight: 700;
  color: var(--ink-soft);
  margin-left: 6px;
  white-space: nowrap;
}

/* ---------- Cards ---------- */

.queue { display: grid; gap: 14px; margin-top: 10px; }

.card {
  position: relative;
  background: var(--card);
  border: 1.6px solid var(--line);
  border-radius: var(--radius-organic);
  padding: 16px 16px 14px;
  box-shadow: var(--shadow-clay);
  animation: card-in 0.3s ease both;
  animation-delay: calc(var(--i, 0) * 55ms);
  transition: box-shadow 0.2s ease, transform 0.2s ease, border-color 0.2s ease;
}

@keyframes card-in {
  from { opacity: 0; transform: translateY(7px); }
  to { opacity: 1; transform: none; }
}

.card:hover { box-shadow: var(--shadow-clay), var(--shadow-soft); }

.card.open { border-color: var(--line-strong); }

.card.overdue {
  border-color: var(--terra-soft);
  border-left: 5px solid var(--terra);
  background: linear-gradient(0deg, var(--terra-tint) -30%, var(--card) 42%);
}

.card.leaving { animation: poof 0.34s ease forwards; pointer-events: none; }

@keyframes poof {
  40% { opacity: 1; transform: translateY(-3px) rotate(-0.6deg) scale(1.01); }
  100% { opacity: 0; transform: translateY(-12px) rotate(-1.4deg) scale(0.97); }
}

.card-head { display: flex; gap: 14px; align-items: flex-start; }

.portrait {
  flex: none;
  width: 74px; height: 74px;
  border-radius: 58% 42% 52% 48% / 48% 55% 45% 52%;
  display: grid;
  place-items: center;
  border: 1.6px solid rgba(120, 100, 60, 0.16);
}
.portrait svg { width: 66px; height: 66px; display: block; }

.p-fern { background: #e8eeda; }
.p-pothos { background: #f4eccd; }
.p-cactus { background: #dfe9ec; }
.p-calathea { background: #f3e3d6; }

.who { flex: 1; min-width: 0; }

.who h3 {
  font-size: 1.3rem;
  display: flex;
  align-items: baseline;
  gap: 8px;
  flex-wrap: wrap;
}

.species {
  font-family: var(--font-display);
  font-style: italic;
  font-weight: 400;
  font-size: 0.86rem;
  color: var(--ink-soft);
}

.meta {
  display: flex;
  gap: 12px;
  flex-wrap: wrap;
  font-size: 0.82rem;
  color: var(--ink-soft);
  margin-top: 3px;
}
.meta span { display: inline-flex; align-items: center; gap: 5px; }
.meta .ico { color: var(--moss); }

.due {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  margin-top: 8px;
  font-size: 0.8rem;
  font-weight: 700;
  letter-spacing: 0.015em;
  padding: 3px 12px 3px 9px;
  border-radius: 999px;
  border: 1.5px solid transparent;
}

.due .taskword { font-weight: 600; opacity: 0.85; }

.badge-overdue { background: var(--terra-tint); color: var(--terra-deep); border-color: var(--terra-soft); }
.badge-today { background: var(--sun-tint); color: #7a5a15; border-color: #e5cd95; }
.badge-soon { background: var(--leaf-tint); color: var(--moss-deep); border-color: #c8d8b4; }

.pulse {
  width: 9px; height: 9px;
  border-radius: 50%;
  background: var(--terra);
  animation: pulse 1.8s ease-in-out infinite;
}

@keyframes pulse {
  0%, 100% { transform: scale(1); opacity: 1; }
  50% { transform: scale(1.45); opacity: 0.55; }
}

/* ---------- Buttons ---------- */

.card-actions {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
  margin-top: 13px;
  align-items: center;
}

.btn {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  border: 2px solid transparent;
  border-radius: 999px;
  padding: 9px 16px;
  font-weight: 700;
  font-size: 0.92rem;
  cursor: pointer;
  background: none;
  transition: transform 0.12s ease, box-shadow 0.12s ease, background-color 0.15s ease, color 0.15s ease;
  text-align: center;
}

.btn .ico { width: 1.15em; height: 1.15em; }

.btn-primary {
  background: var(--moss-deep);
  color: #fbf8ec;
  box-shadow: 0 3px 0 #2c421f;
}
.btn-primary:hover { background: #4a6b3c; transform: translateY(-1px); box-shadow: 0 4px 0 #2c421f; }
.btn-primary:active { transform: translateY(2px); box-shadow: 0 1px 0 #2c421f; }

.btn-ghost {
  border-color: var(--line-strong);
  color: var(--ink);
  background: var(--card);
  box-shadow: 0 3px 0 rgba(120, 100, 60, 0.16);
}
.btn-ghost:hover { border-color: var(--moss); color: var(--moss-deep); transform: translateY(-1px); }
.btn-ghost:active { transform: translateY(2px); box-shadow: 0 1px 0 rgba(120, 100, 60, 0.16); }

.btn-tiny {
  padding: 5px 12px;
  font-size: 0.78rem;
  border-radius: 999px;
  border: 1.6px solid var(--line-strong);
  background: var(--card);
  font-weight: 700;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  transition: transform 0.12s ease, border-color 0.15s ease, color 0.15s ease;
}
.btn-tiny:hover { border-color: var(--moss); color: var(--moss-deep); transform: translateY(-1px); }
.btn-tiny:active { transform: translateY(1px); }

.btn-toggle { margin-left: auto; }
.btn-toggle .chev { transition: transform 0.22s ease; }
.card.open .btn-toggle .chev { transform: rotate(180deg); }

/* ---------- Detail (expandable) ---------- */

.details {
  margin-top: 14px;
  border-top: 2px dashed var(--line);
  padding-top: 14px;
  animation: unfold 0.28s ease both;
}

@keyframes unfold {
  from { opacity: 0; transform: translateY(-4px); }
  to { opacity: 1; transform: none; }
}

.details h4 {
  font-size: 0.95rem;
  color: var(--moss-deep);
  margin-bottom: 8px;
  display: flex;
  align-items: center;
  gap: 7px;
}

.facts {
  display: grid;
  grid-template-columns: auto 1fr;
  gap: 6px 14px;
  margin: 0 0 14px;
  font-size: 0.9rem;
}
.facts dt {
  font-weight: 700;
  color: var(--ink-soft);
  display: flex;
  align-items: center;
  gap: 6px;
  white-space: nowrap;
}
.facts dt .ico { color: var(--terra); }
.facts dd { margin: 0; }

.note {
  background: var(--sun-tint);
  border-radius: 14px 18px 14px 18px;
  padding: 9px 13px;
  font-size: 0.87rem;
  font-style: italic;
  font-family: var(--font-display);
  color: #6d5416;
  margin-bottom: 14px;
}

.log { display: grid; gap: 0; }
.log li {
  position: relative;
  padding: 2px 0 12px 26px;
  font-size: 0.88rem;
  color: var(--ink-soft);
}
.log li::before {
  content: "";
  position: absolute;
  left: 7px; top: 9px;
  width: 8px; height: 8px;
  border-radius: 50% 50% 50% 2px;
  background: var(--leaf);
  transform: rotate(45deg);
}
.log li::after {
  content: "";
  position: absolute;
  left: 10.5px; top: 20px; bottom: 2px;
  width: 1.6px;
  background: var(--line);
}
.log li:last-child { padding-bottom: 2px; }
.log li:last-child::after { display: none; }
.log .log-what { color: var(--ink); font-weight: 600; }

/* ---------- Water drops delight ---------- */

.drop {
  position: absolute;
  top: 14px;
  width: 9px; height: 9px;
  background: var(--drop);
  border-radius: 0 55% 55% 55%;
  transform: rotate(45deg);
  animation: fall 0.7s cubic-bezier(0.4, 0, 0.7, 1) forwards;
  pointer-events: none;
  z-index: 5;
  opacity: 0.9;
}

@keyframes fall {
  to { transform: rotate(45deg) translateY(72px) scale(0.7); opacity: 0; }
}

/* ---------- Snoozed zone ---------- */

.snoozed-zone { margin-top: 26px; }

.snoozed-zone h2 {
  font-size: 1.05rem;
  color: var(--ink-soft);
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 10px;
}
.snoozed-zone h2 .ico { color: var(--sun); width: 1.2em; height: 1.2em; }

.snoozed-list { display: grid; gap: 10px; }

.snoozed-card {
  display: flex;
  align-items: center;
  gap: 12px;
  background: transparent;
  border: 2px dashed var(--line-strong);
  border-radius: 20px 24px 20px 24px;
  padding: 10px 14px;
  animation: card-in 0.3s ease both;
}

.snoozed-card .portrait { width: 44px; height: 44px; }
.snoozed-card .portrait svg { width: 40px; height: 40px; }

.snoozed-who { flex: 1; min-width: 0; }
.snoozed-who strong { font-family: var(--font-display); font-size: 1rem; }
.snoozed-who small { display: block; color: var(--ink-soft); font-size: 0.78rem; }

/* ---------- All done ---------- */

.alldone {
  background: var(--card);
  border: 1.6px solid var(--line);
  border-radius: var(--radius-panel);
  box-shadow: var(--shadow-clay);
  padding: 30px 24px 28px;
  text-align: center;
  display: grid;
  justify-items: center;
  gap: 10px;
  animation: unfold 0.45s ease both;
}

.alldone-art { width: min(340px, 88%); height: auto; }

.alldone h2 { font-size: clamp(1.4rem, 4vw, 1.8rem); color: var(--moss-deep); }
.alldone p { color: var(--ink-soft); max-width: 40ch; }
.alldone .btn { margin-top: 8px; }

.sunrays { animation: slow-spin 36s linear infinite; transform-origin: 110px 44px; }
@keyframes slow-spin { to { transform: rotate(360deg); } }

/* ---------- Leafy sway (portraits & art) ---------- */

.leafy { transform-origin: 50% 92%; }

.card:hover .leafy,
.card:focus-within .leafy,
.alldone .leafy {
  animation: sway 2.8s ease-in-out infinite;
}
.alldone .leafy-2 { animation-delay: -0.9s; }
.alldone .leafy-3 { animation-delay: -1.8s; }

@keyframes sway {
  0%, 100% { transform: rotate(-2.2deg); }
  50% { transform: rotate(2.6deg); }
}

/* ---------- Side panels ---------- */

.panel {
  background: var(--card);
  border: 1.6px solid var(--line);
  border-radius: var(--radius-panel);
  box-shadow: var(--shadow-clay);
  padding: 20px 20px 18px;
}

.panel h2 {
  font-size: 1.05rem;
  color: var(--moss-deep);
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 14px;
}
.panel h2 .ico { width: 1.15em; height: 1.15em; color: var(--terra); }

/* Week rhythm */

.bars {
  display: flex;
  align-items: flex-end;
  gap: 7px;
  height: 104px;
  padding: 0 2px;
}

.barcol {
  flex: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: flex-end;
  gap: 6px;
  height: 100%;
}

.bar {
  width: 100%;
  max-width: 26px;
  border-radius: 999px 999px 7px 7px;
  background: linear-gradient(180deg, var(--leaf) 0%, var(--moss) 85%);
  position: relative;
  animation: grow 0.6s cubic-bezier(0.34, 1.4, 0.64, 1) both;
  transform-origin: bottom;
}

@keyframes grow { from { transform: scaleY(0.05); } to { transform: scaleY(1); } }

.barcol.today .bar { background: linear-gradient(180deg, var(--sun) 0%, var(--terra) 130%); }

.bar-leaf {
  position: absolute;
  top: -9px; left: 50%;
  width: 12px; height: 12px;
  background: var(--moss-deep);
  border-radius: 0 70% 0 70%;
  transform: translateX(-50%) rotate(8deg);
}
.barcol.today .bar-leaf { background: var(--terra-deep); }

.bar-label {
  font-size: 0.72rem;
  font-weight: 700;
  color: var(--ink-soft);
  letter-spacing: 0.04em;
}
.barcol.today .bar-label {
  color: var(--terra-deep);
  position: relative;
}
.barcol.today .bar-label::after {
  content: "";
  position: absolute;
  left: -2px; right: -2px; bottom: -4px;
  height: 2.4px;
  border-radius: 2px;
  background: var(--terra);
}

.soil {
  height: 8px;
  border-radius: 999px;
  background: linear-gradient(180deg, #b18a5e, #96714a);
  margin: 8px 2px 0;
}

.rhythm-caption {
  margin-top: 12px;
  font-size: 0.84rem;
  color: var(--ink-soft);
  font-style: italic;
  font-family: var(--font-display);
}

/* Done panel */

.done-list { display: grid; gap: 8px; }

.done-row {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 8px 12px;
  background: var(--leaf-tint);
  border-radius: 16px 18px 16px 18px;
  font-size: 0.9rem;
  animation: pop-in 0.35s cubic-bezier(0.34, 1.56, 0.64, 1) both;
}

@keyframes pop-in {
  from { opacity: 0; transform: scale(0.85); }
  to { opacity: 1; transform: scale(1); }
}

.done-row .tick { color: var(--moss-deep); width: 1.25em; height: 1.25em; }
.done-row strong { font-family: var(--font-display); }
.done-row small { color: var(--ink-soft); }
.done-row .btn-tiny { margin-left: auto; }

.done-empty {
  font-size: 0.86rem;
  color: var(--ink-soft);
  font-style: italic;
  font-family: var(--font-display);
}

/* Tip panel */

.tip-panel blockquote {
  margin: 0;
  font-family: var(--font-display);
  font-size: 0.95rem;
  line-height: 1.6;
  color: var(--ink);
  border-left: 4px solid var(--sun);
  padding-left: 14px;
}
.tip-sign { text-align: right; color: var(--ink-soft); font-size: 0.82rem; margin-top: 8px; font-style: italic; }

/* ---------- Toast ---------- */

.toast {
  position: fixed;
  left: 50%;
  bottom: 18px;
  transform: translateX(-50%);
  z-index: 50;
  display: flex;
  align-items: center;
  gap: 14px;
  max-width: min(94vw, 460px);
  background: var(--ink);
  color: #f4efdf;
  border-radius: 20px 22px 20px 22px;
  padding: 12px 14px 12px 18px;
  box-shadow: 0 12px 30px rgba(40, 34, 16, 0.35);
  animation: toast-in 0.3s cubic-bezier(0.34, 1.4, 0.64, 1) both;
}

@keyframes toast-in {
  from { opacity: 0; transform: translate(-50%, 16px) scale(0.96); }
  to { opacity: 1; transform: translate(-50%, 0) scale(1); }
}

.toast-msg { font-size: 0.92rem; font-weight: 600; }
.toast-msg .toast-plant { color: var(--sun); }

.btn-undo {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  background: var(--sun);
  color: var(--ink);
  border: none;
  border-radius: 999px;
  padding: 7px 14px;
  font-weight: 800;
  font-size: 0.84rem;
  cursor: pointer;
  white-space: nowrap;
  transition: transform 0.12s ease, background-color 0.15s ease;
}
.btn-undo:hover { background: #f2c469; transform: translateY(-1px); }
.btn-undo:active { transform: translateY(1px); }
.btn-undo .ico { width: 1.1em; height: 1.1em; }

/* ---------- Footer & misc ---------- */

.foot {
  margin-top: 40px;
  text-align: center;
  color: var(--ink-soft);
  font-size: 0.82rem;
  font-style: italic;
  font-family: var(--font-display);
}

.noscript {
  margin: 20px 16px;
  padding: 14px 18px;
  background: var(--terra-tint);
  border: 1.6px solid var(--terra-soft);
  border-radius: 16px;
  color: var(--terra-deep);
  font-weight: 600;
}

@media (max-width: 420px) {
  .portrait { width: 62px; height: 62px; }
  .portrait svg { width: 56px; height: 56px; }
  .card { padding: 14px 13px 12px; }
  .btn-toggle { margin-left: 0; }
  .card-actions .btn { flex: 1 1 auto; justify-content: center; }
}

@media (min-width: 560px) {
  .card { padding: 18px 20px 16px; }
}

/* ---------- Reduced motion ---------- */

@media (prefers-reduced-motion: reduce) {
  html { scroll-behavior: auto; }
  *, *::before, *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }
  .card.leaving { opacity: 0; }
}

