    var f = pendingFocus;
    pendingFocus = null;
    var card = f.id ? document.querySelector('.card[data-id="' + f.id + '"], .snoozed-card[data-id="' + f.id + '"]') : null;
    var target = card ? (card.querySelector(".btn-primary") || card.querySelector(".btn-tiny")) : null;
    if (!target) target = document.querySelector(".card .btn-primary");
    if (!target && !$("alldone").hidden) target = $("alldone");
    if (target) target.focus();
  }

  function showToast(html, undoFn) {
    var toast = $("toast");
    $("toast-msg").innerHTML = html;
    var undo = $("toast-undo");
    currentUndo = undoFn || null;
    undo.hidden = !undoFn;
    toast.hidden = false;
    clearTimeout(toastTimer);
    toastTimer = setTimeout(hideToast, 7000);
  }

  function hideToast() {
    clearTimeout(toastTimer);
    $("toast").hidden = true;
    $("toast-undo").hidden = true;
    currentUndo = null;
  }

  function announce(msg) {
    $("progress-sr").textContent = msg;
  }

  function spawnDrops(card) {
    for (var i = 0; i < 8; i++) {
      var d = document.createElement("span");
      d.className = "drop";
      d.style.left = 12 + Math.random() * 74 + "%";
      d.style.animationDelay = Math.random() * 0.28 + "s";
      card.appendChild(d);
      d.addEventListener("animationend", function () { this.remove(); });
    }
    setTimeout(function () {
      var left = card.querySelectorAll(".drop");
      for (var j = 0; j < left.length; j++) left[j].remove();
    }, 1600);
  }

  function animateOut(el, then) {
    if (reduce.matches || !el) { then(); return; }
    el.classList.add("leaving");
    setTimeout(then, 330);
  }

  function water(id, btn) {
    var p = byId(id);
    if (!p || p.status !== "pending") return;
    p.status = "done";
    var past = (PAST[p.task] || "Done").toLowerCase();
    var card = btn ? btn.closest(".card") : null;
    if (card && !reduce.matches) spawnDrops(card);
    showToast('<span class="toast-plant">' + esc(p.name) + "</span> is " + past + ". Leaves applaud.", function () {
      p.status = "pending";
      pendingFocus = { id: id };
      renderAll();
    });
    pendingFocus = {};
    animateOut(card, renderAll);
  }

  function snooze(id, btn) {
    var p = byId(id);
    if (!p || p.status !== "pending") return;
    p.status = "snoozed";
    var card = btn ? btn.closest(".card") : null;
    showToast('<span class="toast-plant">' + esc(p.name) + "</span> will rest until tomorrow. No judgment.", function () {
      p.status = "pending";
      pendingFocus = { id: id };
      renderAll();
    });
    pendingFocus = {};
    animateOut(card, renderAll);
  }

  function wake(id) {
    var p = byId(id);
    if (!p || p.status === "pending") return;
    var wasSnoozed = p.status === "snoozed";
    p.status = "pending";
    pendingFocus = { id: id };
    renderAll();
    showToast('<span class="toast-plant">' + esc(p.name) + "</span> is back on today's list.", null);
    if (wasSnoozed) announce(p.name + " moved back to today's queue.");
  }

  function toggle(id, btn) {
    var card = btn ? btn.closest(".card") : document.querySelector('.card[data-id="' + id + '"]');
    if (!card) return;
    var det = card.querySelector(".details");
    var opening = det.hidden;
    det.hidden = !opening;
    card.classList.toggle("open", opening);
    if (btn) btn.setAttribute("aria-expanded", opening ? "true" : "false");
    expanded[id] = opening;
    if (opening) announce("Care details for " + byId(id).name + " opened.");
  }

  function reset() {
    plants.forEach(function (p) { p.status = "pending"; });
    expanded = {};
    hideToast();
    renderAll();
    showToast("A fresh day begins. Four friends, zero fuss.", null);
    pendingFocus = {};
    applyPendingFocus();
  }

  function renderRhythm() {
    var max = Math.max.apply(null, week);
    var todayIdx = (new Date().getDay() + 6) % 7;
    var bars = week.map(function (v, i) {
      var h = Math.max(6, Math.round((v / max) * 82));
      return '<div class="barcol' + (i === todayIdx ? " today" : "") + '">' +
        '<div class="bar" style="height:' + h + '%;animation-delay:' + i * 60 + 'ms"><span class="bar-leaf" aria-hidden="true"></span></div>' +
        '<span class="bar-label">' + DAYS[i] + "</span></div>";
    }).join("");
    $("rhythm-bars").innerHTML = bars + "";
    var soil = document.createElement("div");
    soil.className = "soil";
    soil.setAttribute("aria-hidden", "true");
    $("rhythm-bars").after(soil);

    var maxIdx = week.indexOf(max);
    $("rhythm-caption").textContent = DAYS_FULL[maxIdx] + " swings biggest — " + max + " little moments of care. Today is a " + DAYS[todayIdx] + ".";

    var sr = "This week's care rhythm, in moments of care per day. " + DAYS_FULL.map(function (d, i) {
      return d + ": " + week[i] + (i === todayIdx ? " (today)" : "");
    }).join(", ") + ".";
    $("rhythm-sr").textContent = sr;
  }

  function renderDate() {
    var d = new Date();
    var s = d.toLocaleDateString(undefined, { weekday: "long", month: "long", day: "numeric" });
    $("date-chip").textContent = s;
  }

  function bindEvents() {
    document.addEventListener("click", function (e) {
      var btn = e.target.closest("[data-action]");
      if (!btn) return;
      var action = btn.dataset.action;
      var id = btn.dataset.id;
      if (action === "water") water(id, btn);
      else if (action === "snooze") snooze(id, btn);
      else if (action === "toggle") toggle(id, btn);
      else if (action === "wake" || action === "undone") wake(id);
      else if (action === "reset") reset();
    });

    $("toast-undo").addEventListener("click", function () {
      var fn = currentUndo;
      hideToast();
      if (fn) fn();
    });

    var queue = $("queue");
    queue.addEventListener("keydown", function (e) {
      var keys = ["ArrowDown", "ArrowUp", "Home", "End"];
      if (keys.indexOf(e.key) < 0) return;
      var card = e.target.closest(".card");
      if (!card || !queue.contains(card)) return;
      var cards = queue.querySelectorAll(".card");
      var i = Array.prototype.indexOf.call(cards, card);
      var j = i;
      if (e.key === "ArrowDown") j = Math.min(i + 1, cards.length - 1);
      if (e.key === "ArrowUp") j = Math.max(i - 1, 0);
      if (e.key === "Home") j = 0;
      if (e.key === "End") j = cards.length - 1;
      if (j === i) return;
      e.preventDefault();
      var want = e.target.dataset ? e.target.dataset.action : null;
      var target = want ? cards[j].querySelector('[data-action="' + want + '"]') : null;
      target = target || cards[j].querySelector(".btn-primary") || cards[j].querySelector("button");
      if (target) target.focus();
    });

    document.addEventListener("keydown", function (e) {
      if (e.key !== "Escape") return;
      var card = e.target.closest ? e.target.closest(".card") : null;
      if (card && card.classList.contains("open")) {
        var id = card.dataset.id;
        toggle(id, card.querySelector(".btn-toggle"));
        var t = card.querySelector(".btn-toggle");
        if (t) t.focus();
      } else if (!$("toast").hidden) {
        hideToast();
      }
    });
  }

  function init() {
    renderDate();
    renderRhythm();
    bindEvents();
    renderAll();
  }

  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", init);
  } else {
    init();
  }
})();

