harness = src.replace("</body>", """<script>
addEventListener("DOMContentLoaded", function () {
  var mode = location.hash.replace("#", "") || "mixed";
  setTimeout(function () {
    function click(sel) { var el = document.querySelector(sel); if (el) el.click(); }
    if (mode === "mixed") {
      click('.card[data-id="fern"] [data-action="water"]');
      setTimeout(function () { click('.card[data-id="pothos"] [data-action="toggle"]'); }, 500);
      setTimeout(function () { click('.card[data-id="cactus"] [data-action="snooze"]'); }, 1100);
    } else if (mode === "alldone") {
      var ids = ["fern", "pothos", "cactus", "calathea"], i = 0;
      (function step() {
        if (i >= ids.length) return;
        click('.card[data-id="' + ids[i] + '"] [data-action="water"]');
        i++; setTimeout(step, 700);
      })();
    } else if (mode === "allsnooze") {
      var ids2 = ["fern", "pothos", "cactus", "calathea"], j = 0;
      (function step2() {
        if (j >= ids2.length) return;
        click('.card[data-id="' + ids2[j] + '"] [data-action="snooze"]');
        j++; setTimeout(step2, 700);
      })();
    }
  }, 300);
});
</script>
</body>""")
open(".ff-tmp/harness.html", "w").write(harness)
print("harness written")
EOF

