src = open("index.html").read()
src = src.replace('href="styles.css"', 'href="../styles.css"').replace('src="app.js"', '<script>window.matchMedia=function(q){return{matches:q.indexOf("prefers-reduced-motion")>=0,media:q,addEventListener:function(){},addListener:function(){},removeListener:function(){}};};</script>\n<script src="../app.js"></script>')
src = src.replace("</head>", '<style>*,*::before,*::after{animation:none !important;transition:none !important}</style>\n<pre id="dbg" style="background:#fff;font:12px monospace;white-space:pre-wrap;margin:0;padding:6px;border-bottom:2px solid #333"></pre>\n</head>')
src = src.replace("</body>", """<script>
addEventListener("DOMContentLoaded", function () {
  var log = [];
  function click(sel) { var el = document.querySelector(sel); if (el) el.click(); }
  click('.card[data-id="fern"] [data-action="water"]');
  var first = document.querySelector('.card .btn-primary');
  if (first) { first.focus(); log.push("focus1=" + (document.activeElement.getAttribute("aria-label") || document.activeElement.tagName)); }
  if (first) first.dispatchEvent(new KeyboardEvent("keydown", { key: "ArrowDown", bubbles: true, cancelable: true }));
  log.push("focus2=" + (document.activeElement.getAttribute("aria-label") || document.activeElement.tagName));
  var tog = document.querySelector('.card .btn-toggle');
  if (tog) { tog.click(); log.push("expanded=" + tog.getAttribute("aria-expanded") + " detailsHidden=" + document.querySelector('.card .details').hidden); tog.click(); log.push("collapsed=" + (tog.getAttribute("aria-expanded") === "false")); }
  document.querySelector('.card .btn-toggle').dispatchEvent(new KeyboardEvent("keydown", { key: "Escape", bubbles: true, cancelable: true }));
  log.push("afterEsc detailsHidden=" + document.querySelector('.card .details').hidden);
  document.getElementById("dbg").textContent = log.join(" | ");
});
</script>
</body>""")
open(".ff-tmp/kb.html", "w").write(src)
print("kb harness")
EOF
